from pathlib import Path
p=Path('games/wip/index.html')
s=p.read_text()
s=s.replace('comboBurst:0};','comboBurst:0,deck:[]};',1)
start=s.index('function makeProblem(){')
end=s.index('\nfunction setHint',start)
new_problem=r'''function shuffled(a){a=a.slice();for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function buildDeck(){const tiers=[[[23,14],[32,18],[41,26],[43,25]],[[56,32],[67,24],[72,35],[84,16]],[[39,47],[58,43],[64,37],[78,46]]];let last=localStorage.getItem('gridBreakerLastOpeningV1')||'',deck=[],sig='',tries=0;do{deck=tiers.flatMap(t=>shuffled(t));sig=deck.slice(0,4).map(p=>p.join('x')).join('|');tries++}while(sig===last&&tries<20);localStorage.setItem('gridBreakerLastOpeningV1',sig);return deck}
function makeProblem(){if(!S.deck.length)S.deck=buildDeck();let prevA=S.a,prevB=S.b,p;if(S.node<=S.deck.length)p=S.deck[S.node-1];else{do{let lo=S.node<20?2:3;p=[lo*10+Math.ceil(Math.random()*9),(1+Math.floor(Math.random()*5))*10+Math.ceil(Math.random()*9)]}while((p[0]===prevA&&p[1]===prevB)||(p[0]===prevB&&p[1]===prevA))}S.a=p[0];S.b=p[1];let A=splitNum(S.a),B=splitNum(S.b);S.parts=[[A[0],B[0]],[A[1],B[0]],[A[0],B[1]],[A[1],B[1]]];S.solved=[false,false,false,false];S.split=true;S.total=null;S.enemyMax=100+S.node*12;S.enemy=S.enemyMax;S.enemyKind=(S.node-1)%4;S.lastPart=-1;S.enemyCracks=0;S.enemyHit=0;S.comboBurst=0;renderUI();setHint('Each rectangle is a partial product. Charge all four, then combine them.')}
'''
s=s[:start]+new_problem+s[end:]
start=s.index('function draw(){')
end=s.index('terms.forEach((b,i)=>b.onclick',start)
new_draw=r'''const ENEMY_NAMES=['FACTOR FIEND','CARRY CRAB','GRID WRAITH','PRODUCT GOLEM'];
const ENEMY_PALS=[['#24152c','#71345f','#d9659b','#ffd0e5'],['#2a2118','#73532d','#d89b45','#ffe075'],['#0d2530','#1d6570','#48c0c9','#c8ffff'],['#211a32','#59427e','#9873d0','#e4d7ff']];
function drawPixelEnemy(kind,cx,cy,t){const p=4,hit=S.enemyHit,frame=Math.floor(t*3)%2,pal=ENEMY_PALS[kind];let recoil=hit?Math.round(Math.sin(t*90)*8*hit*S.enemyHitDir):0,bob=Math.round(Math.sin(t*2.5)*2);x.save();x.translate(Math.round(cx+recoil),Math.round(cy+bob));x.scale(1+hit*.12,1-hit*.08);const R=(gx,gy,w,h,c)=>{x.fillStyle=pal[c];x.fillRect(gx*p,gy*p,w*p,h*p)};x.fillStyle='#050912';x.fillRect(-9*p,10*p,18*p,2*p);
if(kind===0){R(-7,-7,14,13,1);R(-5,-9,10,2,2);R(-9,-8,3,4,2);R(6,-8,3,4,2);R(-8,5,4,4,1);R(4,5,4,4,1);R(-5,-5,10,5,2);R(-4,-4,3,2,3);R(1,-4,3,2,3);R(-3,1,6,2,0);R(-1,2,2,1,3);if(frame){R(-10,0,3,2,2);R(7,-1,3,2,2)}else{R(-10,-1,3,2,2);R(7,0,3,2,2)}}
else if(kind===1){R(-7,-5,14,10,1);R(-5,-7,10,3,2);R(-9,-3,3,5,2);R(6,-3,3,5,2);R(-12,-5,3,3,2);R(9,-5,3,3,2);R(-13,-7,4,2,3);R(9,-7,4,2,3);R(-6,4,4,3,0);R(2,4,4,3,0);R(-4,-3,3,2,3);R(1,-3,3,2,3);R(-2,1,4,2,0);if(frame){R(-11,2,3,1,2);R(8,1,3,1,2)}else{R(-11,1,3,1,2);R(8,2,3,1,2)}}
else if(kind===2){R(-5,-9,10,13,1);R(-7,-5,2,7,2);R(5,-5,2,7,2);R(-4,-8,8,5,2);R(-3,-6,2,2,3);R(1,-6,2,2,3);R(-2,-2,4,2,0);R(-5,4,3,5,1);R(2,4,3,5,1);R(-2,4,4,3,2);if(frame){R(-6,8,3,2,2);R(3,7,3,2,2)}else{R(-6,7,3,2,2);R(3,8,3,2,2)}}
else{R(-8,-6,16,12,1);R(-5,-10,10,5,1);R(-4,-9,8,3,2);R(-11,-5,3,9,2);R(8,-5,3,9,2);R(-7,5,5,5,1);R(2,5,5,5,1);R(-5,-4,10,6,2);R(-4,-3,3,2,3);R(1,-3,3,2,3);R(-2,1,4,2,0);R(-10,3,3,2,3);R(7,3,3,2,3);if(frame){R(-11,-7,3,2,2);R(8,-6,3,2,2)}else{R(-11,-6,3,2,2);R(8,-7,3,2,2)}}
x.fillStyle=pal[3];x.fillRect(-4*p,-9*p,3*p,p);x.fillStyle='#fff5c7';const cracks=[[-2,-1],[2,0],[-4,2],[4,-2],[-1,4],[1,-5],[-6,0],[5,3]];for(let i=0;i<S.enemyCracks;i++){let [ax,ay]=cracks[i];x.fillRect(ax*p,ay*p,p,p);x.fillRect((ax+(i%2?1:-1))*p,(ay+1)*p,p,p)}if(hit>.05){x.globalAlpha=Math.min(.75,hit*1.8);x.fillStyle='#fff';x.fillRect(-8*p,-8*p,16*p,16*p);x.globalAlpha=1}x.restore();x.textAlign='center';x.font='900 9px monospace';x.fillStyle=pal[3];x.fillText(ENEMY_NAMES[kind],cx,cy-49);x.font='900 11px monospace';x.fillStyle='#eef8ff';x.fillText(S.a+'×'+S.b,cx,cy+50)}
function drawPixelBeam(b){let life=clamp(b.t*2,0,1),steps=b.combine?18:13,size=b.combine?6:4;x.globalAlpha=life;x.fillStyle=b.combine?'#ffd36e':'#73dcff';for(let i=0;i<=steps;i++){let q=i/steps,px=Math.round(b.x1+(b.x2-b.x1)*q),py=Math.round(b.y1+(b.y2-b.y1)*q);if(i%2===0||b.combine)x.fillRect(px-size/2,py-size/2,size,size)}x.globalAlpha=1}
function draw(){x.clearRect(0,0,W,H);let t=performance.now()/1000,cx=W*.5,cy=H*.47,g=gridGeom();x.fillStyle='rgba(115,220,255,.08)';for(let yy=54;yy<H-40;yy+=32)for(let xx=18;xx<W;xx+=40)if(((xx+yy)/8|0)%3===0)x.fillRect(xx,yy,2,2);if(S.split){let {A,B,gw,gh,gx,gy,vx,hy,rects}=g;x.fillStyle='rgba(8,18,32,.72)';x.fillRect(gx,gy,gw,gh);rects.forEach((r,i)=>{let charged=S.solved[i],pulse=charged?.24+.06*Math.sin(t*6+i):.035,col=i===0?'115,220,255':i===1?'255,211,110':i===2?'255,143,179':'178,156,255';x.fillStyle='rgba('+col+','+pulse+')';x.fillRect(r.x,r.y,r.w,r.h);x.strokeStyle=charged?'rgba('+col+',.95)':'rgba(96,126,156,.55)';x.lineWidth=charged?2:1;x.strokeRect(Math.round(r.x)+.5,Math.round(r.y)+.5,Math.round(r.w)-1,Math.round(r.h)-1);if(charged){x.fillStyle='rgba('+col+',.18)';for(let yy=r.y+5;yy<r.y+r.h;yy+=8)for(let xx=r.x+5;xx<r.x+r.w;xx+=8)if(((xx+yy)/8|0)%2===0)x.fillRect(Math.round(xx),Math.round(yy),3,3)}x.fillStyle=charged?'#eef8ff':'#91a7bd';x.font='900 9px monospace';x.textAlign='center';x.fillText(S.parts[i][0]+'×'+S.parts[i][1],r.x+r.w/2,r.y+r.h/2-3);x.fillText(charged?String(S.parts[i][0]*S.parts[i][1]):'?',r.x+r.w/2,r.y+r.h/2+10)});x.strokeStyle='#557897';x.lineWidth=1;x.strokeRect(gx,gy,gw,gh);x.beginPath();x.moveTo(vx,gy);x.lineTo(vx,gy+gh);x.moveTo(gx,hy);x.lineTo(gx+gw,hy);x.stroke();x.fillStyle='#cfe8ff';x.font='900 9px monospace';x.fillText(A[0],gx+(vx-gx)/2,gy-5);x.fillText(A[1],vx+(gx+gw-vx)/2,gy-5);x.fillText(B[0],gx-16,gy+(hy-gy)/2);x.fillText(B[1],gx-16,hy+(gy+gh-hy)/2)}drawPixelEnemy(S.enemyKind,cx,cy,t);for(const b of S.beams){b.t-=1/60;drawPixelBeam(b)}S.beams=S.beams.filter(b=>b.t>0);if(S.enemyHit>0)S.enemyHit=Math.max(0,S.enemyHit-1/34);if(S.combineFlash>0)S.combineFlash=Math.max(0,S.combineFlash-1/30);if(S.streak>=4){let lvl=Math.min(4,Math.floor(S.streak/4)),count=4+lvl*2;for(let i=0;i<count;i++){let a=t*(1+lvl*.15)+i*Math.PI*2/count,r=58+lvl*9+(i%2)*7;x.fillStyle=lvl>=3?'#ffd36e':'#73dcff';let sz=lvl>=3?5:4;x.fillRect(Math.round(cx+Math.cos(a)*r-sz/2),Math.round(cy+Math.sin(a)*r-sz/2),sz,sz)}let label=S.streak>=12?'OVERDRIVE':S.streak>=8?'SURGE':'CHAIN';x.fillStyle=S.streak>=12?'#ffd36e':'#73dcff';x.font='900 10px monospace';x.textAlign='center';x.fillText(label+' x'+S.streak,cx,cy-70)}for(const q of S.particles){q.t-=1/60;q.x+=q.vx/60;q.y+=q.vy/60;x.globalAlpha=clamp(q.t*2,0,1);x.fillStyle='#ffd36e';x.fillRect(Math.round(q.x),Math.round(q.y),4,4)}S.particles=S.particles.filter(q=>q.t>0);x.globalAlpha=1;x.textAlign='left';requestAnimationFrame(draw)}requestAnimationFrame(draw);
'''
s=s[:start]+new_draw+s[end:]
s=s.replace('Split both numbers. Then break the product into four smaller attacks.','Each rectangle is a partial product. Charge all four, then combine them.',1)
